             PrintWriter pw = new PrintWriter(System.out)) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            int n = Integer.parseInt(st.nextToken());
            int k = Integer.parseInt(st.nextToken());
            int[] v = new int[10];
            st = new StringTokenizer(br.readLine());
            for (int i = 0; i < k; i++) {
                v[Integer.parseInt(st.nextToken())] = 1;
            }
            int[] ans = {1};
            int p = n / 2;
            while (true) {
                if ((p & 1) == 1) {
                    ans = multiply(ans, v, 998244353);
                }
                p >>= 1;
                if (p == 0) break;
                v = multiply(v, v, 998244353);
            }
            long res = 0;
            for (int x : ans) {
                res = (res + (long) x * x) % 998244353;
            }
            pw.println(res);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    int[] multiply(int[] a, int[] b, int mod) {
        int need = a.length + b.length - 1;
        int n = Math.max(2, Integer.highestOneBit(need - 1) << 1);

        double[] ar = new double[n], ai = new double[n];
        for (int i = 0; i < a.length; i++) {
            int x = ((a[i] % mod) + mod) % mod;
            ar[i] = x & 0x7FFF;
            ai[i] = x >>> 15;
        }
        fft(ar, ai, false);

        double[] br = new double[n], bi = new double[n];
        for (int i = 0; i < b.length; i++) {
            int x = ((b[i] % mod) + mod) % mod;
            br[i] = x & 0x7FFF;
            bi[i] = x >>> 15;
        }
        fft(br, bi, false);

        double[] cr1 = new double[n], ci1 = new double[n];
        double[] cr2 = new double[n], ci2 = new double[n];

        for (int i = 0; i < n; i++) {
            int j = (n - i) & (n - 1);
            double a1r = (ar[i] + ar[j]) * 0.5;
            double a1i = (ai[i] - ai[j]) * 0.5;
            double a2r = (ai[i] + ai[j]) * 0.5;
            double a2i = (ar[j] - ar[i]) * 0.5;

            double b1r = (br[i] + br[j]) * 0.5;
            double b1i = (bi[i] - bi[j]) * 0.5;
            double b2r = (bi[i] + bi[j]) * 0.5;
            double b2i = (br[j] - br[i]) * 0.5;

            cr1[i] = a1r * b1r - a1i * b1i - a2r * b2i - a2i * b2r;
            ci1[i] = a1r * b1i + a1i * b1r + a2r * b2r - a2i * b2i;
            cr2[i] = a1r * b2r - a1i * b2i + a2r * b1r - a2i * b1i;
            ci2[i] = a1r * b2i + a1i * b2r + a2r * b1i + a2i * b1r;
        }

        fft(cr1, ci1, true);
        fft(cr2, ci2, true);

        int[] res = new int[need];
        for (int i = 0; i < need; i++) {
            long aa = Math.round(cr1[i]);
            long bb = Math.round(cr2[i]);
            long cc = Math.round(ci1[i]);
            res[i] = (int) ((aa + ((bb % mod) << 15) + ((cc % mod) << 30)) % mod);
        }
        return res;
    }

    void fft(double[] re, double[] im, boolean inv) {
        int n = re.length;
        int shift = 32 - Integer.numberOfTrailingZeros(n);
        for (int i = 1; i < n; i++) {
            int j = Integer.reverse(i << shift);
            if (i < j) {
                double t = re[i]; re[i] = re[j]; re[j] = t;
                t = im[i]; im[i] = im[j]; im[j] = t;
            }
        }

        double[] cosTable = new double[n];
        double[] sinTable = new double[n];
        for (int len = 1; len < n; len <<= 1) {
            for (int i = len; i < (len << 1); i++) {
                double angle = 2 * Math.PI * (i - len) / (len << 1);
                cosTable[i] = Math.cos(angle);
                sinTable[i] = Math.sin(angle);
            }
        }

        for (int len = 2; len <= n; len <<= 1) {
            int half = len >> 1;
            for (int i = 0; i < n; i += len) {
                for (int j = 0; j < half; j++) {
                    double wRe = inv ? cosTable[half + j] : cosTable[half + j];
                    double wIm = inv ? -sinTable[half + j] : sinTable[half + j];

                    double uRe = re[i + j];
                    double uIm = im[i + j];
                    double vRe = re[i + j + half] * wRe - im[i + j + half] * wIm;
                    double vIm = re[i + j + half] * wIm + im[i + j + half] * wRe;

                    re[i + j] = uRe + vRe;
                    im[i + j] = uIm + vIm;
                    re[i + j + half] = uRe - vRe;
                    im[i + j + half] = uIm - vIm;
                }
            }
        }

        if (inv) {
            for (int i = 0; i < n; i++) {
                re[i] /= n;
                im[i] /= n;
            }
        }
    }
